import{_ as o,o as s,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse(`{"title":"2020-05-28 :: Ceph Tech Talk - What''s New In Octopus","description":"","frontmatter":{"title":"2020-05-28 :: Ceph Tech Talk - What''s New In Octopus","date":"2020-05-28T00:00:00.000Z","updated":"2020-05-29T00:00:00.000Z","tags":["Ceph","Octopus 版本","distributed storage","BlueStore","Kubernetes","CSI"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-05-28_-_-_Ceph_Tech_Talk_-_What_s_New_In_Octopus.md","filePath":"posts/2020/2020-05-28_-_-_Ceph_Tech_Talk_-_What_s_New_In_Octopus.md","lastUpdated":1780459816000}`),l={name:"posts/2020/2020-05-28_-_-_Ceph_Tech_Talk_-_What_s_New_In_Octopus.md"};function a(i,t,n,_,h,u){return s(),e("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2020年5月28日</li><li><strong>主题</strong>: Ceph Tech Talk - Octopus 版本更新及新功能介绍</li><li><strong>主讲人</strong>: Josh Durgan (Red Hat) 和 Lance Kramer (Sousa)</li><li><strong>参会人员</strong>: Ceph 社区成员及技术爱好者</li></ul><h4 id="讨论内容" tabindex="-1">讨论内容 <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容&quot;">​</a></h4><ol><li><p><strong>Ceph Octopus 版本更新</strong></p><ul><li><strong>发布时间</strong>: Octopus 版本于2020年3月发布，下一个版本 Pacific 预计于2021年3月发布。</li><li><strong>支持与升级</strong>: 支持从 Luminous、Mimic 和 Nautilus 升级到 Octopus，但 Luminous 需要先升级到 Mimic 或 Nautilus。</li></ul></li><li><p><strong>主要改进与新功能</strong></p><ul><li><strong>可操作性提升</strong>: <ul><li><strong>Orchestrator API</strong>: 实现统一部署和管理，支持容器化部署，简化集群管理。</li><li><strong>Ceph Dashboard</strong>: 界面布局调整，增强用户管理功能，改进 OSD 部署流程。</li></ul></li><li><strong>性能与稳定性</strong>: <ul><li><strong>BlueStore 优化</strong>: 改进预取和压缩机制，优化内存使用和 TRIM 行为。</li><li><strong>健康监控</strong>: 新增网络监控健康警报，改进内部健康警报处理。</li></ul></li><li><strong>多站点支持</strong>: <ul><li><strong>RBD 镜像</strong>: 基于快照的灾难恢复，减少 I/O 开销。</li><li><strong>Garbage Collection</strong>: 使用简单块用于垃圾回收，减少 RocksDB 瓶颈。</li></ul></li><li><strong>生态系统集成</strong>: <ul><li><strong>Ceph CSI 和 Rook</strong>: 增强与 Kubernetes 的集成，支持更多存储模式和操作。</li></ul></li></ul></li><li><p><strong>用户提问与回答</strong></p><ul><li><strong>驱动器故障处理</strong>: Ceph Orchestrator 目前不直接处理驱动器故障，但有计划自动化这一过程。</li><li><strong>SMR 磁盘支持</strong>: 目前不支持，但 Pacific 版本将引入新的后端存储以支持 SMR 磁盘。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>持续优化</strong>: 继续改进 Ceph Orchestrator 的功能，特别是在自动化驱动器故障处理方面。</li><li><strong>新功能开发</strong>: 开发支持 SMR 磁盘的新后端存储，预计在 Pacific 版本中实现。</li><li><strong>社区参与</strong>: 鼓励用户参与 Ceph 的 telemetry 和 crash reporting，以帮助改进产品。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>本次会议详细介绍了 Ceph Octopus 版本的新功能和改进，强调了其在可操作性、性能和多站点支持方面的进步。同时，讨论了未来版本的发展方向和社区参与的重要性。</p>',9)])])}const p=o(l,[["render",a]]);export{g as __pageData,p as default};
